def ensure_program_logo_assets() -> None:
    """Gömülü program logosunu Kurumsal klasöründe hazır tut."""
    LOGO_DIR.mkdir(parents=True, exist_ok=True)
    assets = (
        (PROGRAM_LOGO_FULL, _PROGRAM_LOGO_FULL_B64),
        (PROGRAM_LOGO_ICON, _PROGRAM_LOGO_ICON_B64),
    )
    for target, encoded in assets:
        payload = base64.b64decode(encoded)
        try:
            if not target.exists() or target.read_bytes() != payload:
                target.write_bytes(payload)
        except OSError:
            pass


ensure_program_logo_assets()
