# ============================================================
# FONT KAYDI
# ============================================================
def register_fonts() -> Tuple[str, str]:
    candidates = [
        (
            Path(r"C:\Windows\Fonts\arial.ttf"),
            Path(r"C:\Windows\Fonts\arialbd.ttf"),
            "ArialCustom",
            "ArialCustom-Bold",
        ),
        (
            Path("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"),
            Path("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"),
            "DejaVuCustom",
            "DejaVuCustom-Bold",
        ),
    ]

    for regular, bold, regular_name, bold_name in candidates:
        try:
            if regular.exists() and bold.exists():
                pdfmetrics.registerFont(TTFont(regular_name, str(regular)))
                pdfmetrics.registerFont(TTFont(bold_name, str(bold)))
                return regular_name, bold_name
        except Exception:
            continue

    return "Helvetica", "Helvetica-Bold"


MAIN_FONT, BOLD_FONT = register_fonts()


def register_named_font(candidates: Sequence[Tuple[str, str, str]], fallback: str) -> str:
    """Try to register one of the given font files and return the usable font name."""
    for file_path, font_name, internal_name in candidates:
        try:
            font_path = Path(file_path)
            if font_path.exists():
                pdfmetrics.registerFont(TTFont(internal_name, str(font_path)))
                return internal_name
        except Exception:
            continue
    return fallback


