# DOSYA VE YAPILANDIRMA YARDIMCILARI
# ============================================================
def deep_merge(default: Any, loaded: Any) -> Any:
    if isinstance(default, dict) and isinstance(loaded, dict):
        result = deepcopy(default)
        for key, value in loaded.items():
            result[key] = deep_merge(default[key], value) if key in default else value
        return result
    return loaded


def atomic_write_json(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp_name = tempfile.mkstemp(prefix=path.stem + "_", suffix=".tmp", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as temp_file:
            json.dump(data, temp_file, ensure_ascii=False, indent=4)
            temp_file.flush()
            os.fsync(temp_file.fileno())
        os.replace(temp_name, path)
    finally:
        if os.path.exists(temp_name):
            os.remove(temp_name)


def _normalize_document_type(value: Any) -> str:
    document_type = clean_text(value).upper()
    return document_type if document_type in ("BASARI", "USTUN_BASARI") else "BASARI"


def document_settings_for(config: Dict[str, Any], document_type: Any) -> Dict[str, Any]:
    document_type = _normalize_document_type(document_type)
    by_type = config.get("document_by_type", {})
    settings = by_type.get(document_type)
    if isinstance(settings, dict):
        return settings
    legacy = config.get("document", DEFAULT_CONFIG["document"])
    return legacy if isinstance(legacy, dict) else deepcopy(DEFAULT_CONFIG["document"])


def reasons_for_document_type(config: Dict[str, Any], document_type: Any) -> List[str]:
    document_type = _normalize_document_type(document_type)
    by_type = config.get("gerekceler_by_type", {})
    reasons = by_type.get(document_type)
    if isinstance(reasons, list) and reasons:
        return [clean_text(item) for item in reasons if clean_text(item)]
    legacy = config.get("gerekceler", DEFAULT_CONFIG["gerekceler"])
    return [clean_text(item) for item in legacy if clean_text(item)] or deepcopy(DEFAULT_CONFIG["gerekceler"])


def migrate_document_type_settings(config: Dict[str, Any], loaded: Optional[Dict[str, Any]] = None) -> bool:
    """Eski ortak ayarları ilk geçişte iki belge türüne kopyala; veri kaybı yapma."""
    changed = False
    loaded = loaded if isinstance(loaded, dict) else {}

    legacy_doc = deepcopy(
        loaded.get("document")
        if isinstance(loaded.get("document"), dict)
        else config.get("document", DEFAULT_CONFIG["document"])
    )
    if not isinstance(config.get("document_by_type"), dict):
        config["document_by_type"] = {}
        changed = True

    loaded_doc_by_type = loaded.get("document_by_type")
    for doc_type in ("BASARI", "USTUN_BASARI"):
        # Eski dosyada belge-türü yapısı hiç yoksa mevcut ortak ayarı birebir kopyala.
        if not isinstance(loaded_doc_by_type, dict) or not isinstance(loaded_doc_by_type.get(doc_type), dict):
            config["document_by_type"][doc_type] = deepcopy(legacy_doc)
            changed = True

    legacy_reasons = deepcopy(
        loaded.get("gerekceler")
        if isinstance(loaded.get("gerekceler"), list) and loaded.get("gerekceler")
        else config.get("gerekceler", DEFAULT_CONFIG["gerekceler"])
    )
    if not isinstance(config.get("gerekceler_by_type"), dict):
        config["gerekceler_by_type"] = {}
        changed = True

    loaded_reasons_by_type = loaded.get("gerekceler_by_type")
    for doc_type in ("BASARI", "USTUN_BASARI"):
        if (
            not isinstance(loaded_reasons_by_type, dict)
            or not isinstance(loaded_reasons_by_type.get(doc_type), list)
            or not loaded_reasons_by_type.get(doc_type)
        ):
            config["gerekceler_by_type"][doc_type] = deepcopy(legacy_reasons)
            changed = True

    return changed


def load_config() -> Dict[str, Any]:
    if not CONFIG_FILE.exists():
        config = deepcopy(DEFAULT_CONFIG)
        migrate_document_type_settings(config, config)
        atomic_write_json(CONFIG_FILE, config)
        return config

    try:
        with CONFIG_FILE.open("r", encoding="utf-8") as file:
            loaded = json.load(file)
        config = deep_merge(DEFAULT_CONFIG, loaded)

        # Program adı kullanıcı tarafından değiştirilebilir.
        # Yalnız boş veya eski varsayılan adlardan biri varsa yeni varsayılanı ata.
        current_program_name = clean_text(config.get("program", {}).get("program_adi"))
        legacy_program_names = {
            "",
            "İstanbul Havalimanı Mülki İdare Amirliği Başarı Belgesi Modülü",
            "Başarı Belgesi Otomasyonu",
            "Başarı Belgesi Yönetim ve Basım Otomasyonu",
        }
        if current_program_name in legacy_program_names:
            config.setdefault("program", {})["program_adi"] = APP_TITLE
            loaded.setdefault("program", {})["program_adi"] = APP_TITLE
            atomic_write_json(CONFIG_FILE, config)

        if not config.get("gerekceler"):
            config["gerekceler"] = deepcopy(DEFAULT_CONFIG["gerekceler"])
        if not config.get("amirlers"):
            config["amirlers"] = deepcopy(DEFAULT_CONFIG["amirlers"])

        migrated = migrate_document_type_settings(config, loaded)
        if migrated:
            atomic_write_json(CONFIG_FILE, config)
        return config
    except (OSError, json.JSONDecodeError):
        corrupt_copy = BACKUP_DIR / f"system_config_bozuk_{datetime.now():%Y%m%d_%H%M%S}.json"
        try:
            shutil.copy2(CONFIG_FILE, corrupt_copy)
        except OSError:
            pass
        config = deepcopy(DEFAULT_CONFIG)
        atomic_write_json(CONFIG_FILE, config)
        return config

def save_config(config: Dict[str, Any]) -> None:
    atomic_write_json(CONFIG_FILE, config)


def get_program_info(config: Dict[str, Any]) -> Dict[str, str]:
    program = config.get("program", {})
    return {
        # Program adı varsayılan olarak APP_TITLE gelir; kullanıcı Ayarlar'dan değiştirebilir.
        "program_adi": clean_text(program.get("program_adi")) or APP_TITLE,
        "kurum_adi": clean_text(program.get("kurum_adi")),
        "birim_adi": clean_text(program.get("birim_adi")),
        "belge_turu": clean_text(program.get("belge_turu")) or "Başarı Belgesi",
        "alt_aciklama": clean_text(program.get("alt_aciklama")) or "Belge kayıt, düzenleme ve PDF üretim sistemi",
        "surum": clean_text(program.get("surum")) or "1.0",
    }


def display_program_title(config: Dict[str, Any]) -> str:
    """Ana başlık program adı; kurum adı varsa ayrı alt satırda gösterilir."""
    return get_program_info(config)["program_adi"]


def selected_template(config: Dict[str, Any], document_type: Optional[str] = None) -> Dict[str, Any]:
    templates = config.get("templates", {})
    items = templates.get("items", [])
    selected_id = templates.get("default_id", "dikey_1")
    if document_type:
        selected_id = templates.get("default_by_document_type", {}).get(
            clean_text(document_type).upper(), selected_id
        )
    return next((item for item in items if item.get("id") == selected_id), items[0] if items else {})


def selected_template_path(config: Dict[str, Any], document_type: Optional[str] = None) -> Path:
    item = selected_template(config, document_type=document_type)
    path = TEMPLATE_DIR / clean_text(item.get("filename", "dikey_1.png"))
    if item.get("id") == "dikey_1" and not path.exists() and TEMPLATE_IMAGE.exists():
        return TEMPLATE_IMAGE
    return path


