def get_template_layout(config: Dict[str, Any], template_id: Optional[str] = None) -> Dict[str, Any]:
    templates = config.setdefault("templates", {})
    layouts = templates.setdefault("layouts", {})
    template_id = template_id or templates.get("default_id", "dikey_1")
    defaults = default_template_layouts()
    base = deepcopy(defaults.get(template_id, defaults["dikey_1"]))
    stored = layouts.get(template_id, {})
    if isinstance(stored, dict):
        base.update(stored)
    return base


