def get_connection() -> sqlite3.Connection:
    connection = sqlite3.connect(DB_FILE, timeout=30)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA synchronous = FULL")
    connection.execute("PRAGMA busy_timeout = 30000")
    return connection


def build_record_fingerprint(data: Dict[str, Any]) -> str:
    """Create a stable identity for an otherwise identical certificate record."""
    parts = [
        clean_text(data.get("BELGE_TURU", "BASARI")).upper() or "BASARI",
        clean_tc(data.get("TC_KIMLIK", "")),
        normalize_name_for_match(data.get("AD_SOYAD", "")),
        normalize_name_for_match(data.get("UNVAN", "")),
        normalize_name_for_match(data.get("GOREV_YERI", "")),
        clean_text(data.get("TARIH", "")),
        clean_text(data.get("GEREKCE", "")),
        clean_text(data.get("TALTIF_METNI", "")) or DEFAULT_TALTIF_TEXT,
    ]
    return hashlib.sha256("\x1f".join(parts).encode("utf-8")).hexdigest()


def initialize_database() -> None:
    with get_connection() as connection:
        connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS records (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                belge_turu TEXT NOT NULL DEFAULT 'BASARI',
                tc_kimlik TEXT NOT NULL,
                ad_soyad TEXT NOT NULL,
                unvan TEXT NOT NULL DEFAULT '',
                gorev_yeri TEXT NOT NULL DEFAULT '',
                tarih TEXT,
                yil INTEGER,
                sayi INTEGER,
                olur_yazisi_tarihi TEXT NOT NULL DEFAULT '',
                olur_yazisi_sayisi TEXT NOT NULL DEFAULT '',
                gerekce TEXT NOT NULL DEFAULT '',
                taltif_metni TEXT NOT NULL DEFAULT '',
                foto_path TEXT NOT NULL DEFAULT '',
                signature_mode TEXT NOT NULL DEFAULT 'WET',
                signer_name TEXT NOT NULL DEFAULT '',
                signer_title TEXT NOT NULL DEFAULT '',
                signature_path TEXT NOT NULL DEFAULT '',
                status TEXT NOT NULL DEFAULT 'TASLAK',
                finalized_at TEXT,
                delivered_at TEXT,
                reopened_at TEXT,
                reopen_reason TEXT NOT NULL DEFAULT '',
                cancelled_at TEXT,
                cancel_reason TEXT NOT NULL DEFAULT '',
                record_fingerprint TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(belge_turu, yil, sayi)
            );

            CREATE INDEX IF NOT EXISTS idx_records_tc ON records(tc_kimlik);
            CREATE INDEX IF NOT EXISTS idx_records_name ON records(ad_soyad);
            CREATE INDEX IF NOT EXISTS idx_records_year_number ON records(yil, sayi);

            CREATE TABLE IF NOT EXISTS counters (
                belge_turu TEXT NOT NULL DEFAULT 'BASARI',
                yil INTEGER NOT NULL,
                last_number INTEGER NOT NULL DEFAULT 0,
                PRIMARY KEY(belge_turu, yil)
            );

            CREATE TABLE IF NOT EXISTS audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                action TEXT NOT NULL,
                record_id INTEGER,
                details TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL
            );
            """
        )
        # Eski tek sayaç şemasını belge türüne göre ayrı sayaç yapısına güvenle dönüştür.
        records_sql_row = connection.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' AND name='records'"
        ).fetchone()
        records_sql = (records_sql_row[0] or "") if records_sql_row else ""
        records_info_now = connection.execute("PRAGMA table_info(records)").fetchall()
        records_columns_now = {row[1] for row in records_info_now}
        records_notnull_now = {row[1]: int(row[3]) for row in records_info_now}
        needs_records_rebuild = (
            "belge_turu" not in records_columns_now
            or re.search(r"UNIQUE\s*\(\s*yil\s*,\s*sayi\s*\)", records_sql, re.IGNORECASE) is not None
            or any(records_notnull_now.get(name, 0) == 1 for name in ("tarih", "yil", "sayi"))
        )
        if needs_records_rebuild:
            connection.execute("PRAGMA foreign_keys = OFF")
            connection.execute(
                """
                CREATE TABLE records_new (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    belge_turu TEXT NOT NULL DEFAULT 'BASARI',
                    tc_kimlik TEXT NOT NULL,
                    ad_soyad TEXT NOT NULL,
                    unvan TEXT NOT NULL DEFAULT '',
                    gorev_yeri TEXT NOT NULL DEFAULT '',
                    tarih TEXT,
                    yil INTEGER,
                    sayi INTEGER,
                    olur_yazisi_tarihi TEXT NOT NULL DEFAULT '',
                    olur_yazisi_sayisi TEXT NOT NULL DEFAULT '',
                    gerekce TEXT NOT NULL DEFAULT '',
                    taltif_metni TEXT NOT NULL DEFAULT '',
                    foto_path TEXT NOT NULL DEFAULT '',
                    signature_mode TEXT NOT NULL DEFAULT 'WET',
                    signer_name TEXT NOT NULL DEFAULT '',
                    signer_title TEXT NOT NULL DEFAULT '',
                    signature_path TEXT NOT NULL DEFAULT '',
                    status TEXT NOT NULL DEFAULT 'TASLAK',
                    finalized_at TEXT,
                    delivered_at TEXT,
                    reopened_at TEXT,
                    reopen_reason TEXT NOT NULL DEFAULT '',
                    cancelled_at TEXT,
                    cancel_reason TEXT NOT NULL DEFAULT '',
                    record_fingerprint TEXT NOT NULL DEFAULT '',
                    created_at TEXT NOT NULL,
                    updated_at TEXT NOT NULL,
                    UNIQUE(belge_turu, yil, sayi)
                )
                """
            )
            old_cols = {row[1] for row in connection.execute("PRAGMA table_info(records)").fetchall()}
            src_type = "COALESCE(NULLIF(TRIM(belge_turu), ''), 'BASARI')" if "belge_turu" in old_cols else "'BASARI'"
            def col(name, fallback): return name if name in old_cols else fallback
            connection.execute(
                f"""
                INSERT INTO records_new(
                    id, belge_turu, tc_kimlik, ad_soyad, unvan, gorev_yeri, tarih, yil, sayi,
                    olur_yazisi_tarihi, olur_yazisi_sayisi,
                    gerekce, taltif_metni, foto_path, signature_mode, signer_name, signer_title,
                    signature_path, status, finalized_at, delivered_at, reopened_at, reopen_reason,
                    cancelled_at, cancel_reason, record_fingerprint, created_at, updated_at
                )
                SELECT id, {src_type}, tc_kimlik, ad_soyad, unvan, gorev_yeri, tarih, yil, sayi,
                    {col('olur_yazisi_tarihi', "''")}, {col('olur_yazisi_sayisi', "''")},
                    gerekce, {col('taltif_metni', "''")}, foto_path, {col('signature_mode', "'WET'")},
                    {col('signer_name', "''")}, {col('signer_title', "''")}, {col('signature_path', "''")},
                    {col('status', "'TASLAK'")}, {col('finalized_at', 'NULL')}, {col('delivered_at', 'NULL')},
                    {col('reopened_at', 'NULL')}, {col('reopen_reason', "''")}, {col('cancelled_at', 'NULL')}, {col('cancel_reason', "''")},
                    {col('record_fingerprint', "''")}, created_at, updated_at
                FROM records
                """
            )
            connection.execute("DROP TABLE records")
            connection.execute("ALTER TABLE records_new RENAME TO records")
            connection.execute("PRAGMA foreign_keys = ON")

        counter_columns = {row[1] for row in connection.execute("PRAGMA table_info(counters)").fetchall()}
        if "belge_turu" not in counter_columns:
            connection.execute(
                """CREATE TABLE counters_new (
                    belge_turu TEXT NOT NULL DEFAULT 'BASARI',
                    yil INTEGER NOT NULL,
                    last_number INTEGER NOT NULL DEFAULT 0,
                    PRIMARY KEY(belge_turu, yil)
                )"""
            )
            connection.execute(
                "INSERT INTO counters_new(belge_turu, yil, last_number) SELECT 'BASARI', yil, last_number FROM counters"
            )
            connection.execute("DROP TABLE counters")
            connection.execute("ALTER TABLE counters_new RENAME TO counters")

        connection.execute("CREATE INDEX IF NOT EXISTS idx_records_tc ON records(tc_kimlik)")
        connection.execute("CREATE INDEX IF NOT EXISTS idx_records_name ON records(ad_soyad)")
        connection.execute("CREATE INDEX IF NOT EXISTS idx_records_year_number ON records(yil, sayi)")

        columns = {row[1] for row in connection.execute("PRAGMA table_info(records)").fetchall()}
        migrations = {
            "belge_turu": "TEXT NOT NULL DEFAULT 'BASARI'",
            "olur_yazisi_tarihi": "TEXT NOT NULL DEFAULT ''",
            "olur_yazisi_sayisi": "TEXT NOT NULL DEFAULT ''",
            "taltif_metni": "TEXT NOT NULL DEFAULT ''",
            "status": "TEXT NOT NULL DEFAULT 'TASLAK'",
            "finalized_at": "TEXT",
            "delivered_at": "TEXT",
            "reopened_at": "TEXT",
            "reopen_reason": "TEXT NOT NULL DEFAULT ''",
            "cancelled_at": "TEXT",
            "cancel_reason": "TEXT NOT NULL DEFAULT ''",
            "record_fingerprint": "TEXT NOT NULL DEFAULT ''",
            "signature_mode": "TEXT NOT NULL DEFAULT 'WET'",
            "signer_name": "TEXT NOT NULL DEFAULT ''",
            "signer_title": "TEXT NOT NULL DEFAULT ''",
            "signature_path": "TEXT NOT NULL DEFAULT ''",
        }
        for column_name, definition in migrations.items():
            if column_name not in columns:
                connection.execute(f"ALTER TABLE records ADD COLUMN {column_name} {definition}")
        connection.execute(
            "UPDATE records SET taltif_metni = ? WHERE TRIM(COALESCE(taltif_metni, '')) = ''",
            (DEFAULT_TALTIF_TEXT,),
        )
        connection.execute(
            "UPDATE records SET status = 'TASLAK' WHERE TRIM(COALESCE(status, '')) = ''"
        )

        # Yeni iş akışına geriye uyumlu geçiş.
        # Eski KESINLESTI = geçmiş sistemde "İmzalandı ve Teslim Edildi".
        connection.execute(
            """
            UPDATE records
            SET status='TESLIM_EDILDI',
                delivered_at=COALESCE(delivered_at, finalized_at)
            WHERE status='KESINLESTI'
            """
        )
        # Çok eski DUZELTME kayıtları: numaralıysa Olur Listesinde, numarasızsa Taslak.
        connection.execute(
            """
            UPDATE records
            SET status = CASE
                WHEN yil IS NOT NULL AND sayi IS NOT NULL AND TRIM(COALESCE(tarih, '')) <> ''
                    THEN 'OLUR_LISTESINDE'
                ELSE 'TASLAK'
            END
            WHERE status='DUZELTME'
            """
        )
        rows_without_fingerprint = connection.execute(
            "SELECT * FROM records WHERE TRIM(COALESCE(record_fingerprint, '')) = ''"
        ).fetchall()
        for row in rows_without_fingerprint:
            fingerprint = build_record_fingerprint({
                "TC_KIMLIK": row["tc_kimlik"],
                "AD_SOYAD": row["ad_soyad"],
                "UNVAN": row["unvan"],
                "GOREV_YERI": row["gorev_yeri"],
                "TARIH": row["tarih"],
                "GEREKCE": row["gerekce"],
                "TALTIF_METNI": row["taltif_metni"],
            })
            # Eski veride aynı içerikte birden fazla kayıt varsa program açılışını
            # engellememek için yalnızca ilk kayda parmak izi atanır.
            if connection.execute(
                "SELECT 1 FROM records WHERE record_fingerprint = ? AND id <> ?",
                (fingerprint, row["id"]),
            ).fetchone() is None:
                connection.execute(
                    "UPDATE records SET record_fingerprint = ? WHERE id = ?",
                    (fingerprint, row["id"]),
                )
        # Eski sürümlerde record_fingerprint alanı UNIQUE index ile korunuyordu.
        # Bu, aynı personele aynı içerikle ikinci/üçüncü gerçek Başarı Belgesi
        # verilmesini yanlışlıkla "mükerrer" sayıyordu. CREATE ... IF NOT EXISTS
        # mevcut eski UNIQUE indexi değiştirmediği için yalnız kodda fingerprint'i
        # boşaltmak yeterli değildi. Eski UNIQUE indexi kesin olarak kaldırıyoruz.
        connection.execute("DROP INDEX IF EXISTS ux_records_fingerprint")
        connection.execute(
            "CREATE INDEX IF NOT EXISTS ix_records_fingerprint "
            "ON records(record_fingerprint)"
        )

        connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS achievement_history (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                tc_kimlik TEXT NOT NULL,
                ad_soyad TEXT NOT NULL DEFAULT '',
                kurum TEXT NOT NULL,
                tarih TEXT NOT NULL,
                belge_sayi TEXT NOT NULL DEFAULT '',
                kaynak TEXT NOT NULL DEFAULT 'SISTEM_ONCESI',
                dogrulama TEXT NOT NULL DEFAULT 'DOGRULANDI',
                notlar TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );

            CREATE INDEX IF NOT EXISTS idx_achievement_history_tc
                ON achievement_history(tc_kimlik);

            CREATE TABLE IF NOT EXISTS superior_basis (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                superior_record_id INTEGER NOT NULL,
                source_type TEXT NOT NULL,
                source_id INTEGER NOT NULL,
                created_at TEXT NOT NULL,
                UNIQUE(superior_record_id, source_type, source_id),
                FOREIGN KEY(superior_record_id) REFERENCES records(id) ON DELETE CASCADE
            );

            CREATE INDEX IF NOT EXISTS idx_superior_basis_superior
                ON superior_basis(superior_record_id);
            CREATE INDEX IF NOT EXISTS idx_superior_basis_source
                ON superior_basis(source_type, source_id);

            CREATE TABLE IF NOT EXISTS approval_lists (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                belge_turu TEXT NOT NULL,
                created_at TEXT NOT NULL,
                created_by_action TEXT NOT NULL DEFAULT 'MANUAL',
                note TEXT NOT NULL DEFAULT ''
            );

            CREATE TABLE IF NOT EXISTS approval_list_items (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                approval_list_id INTEGER NOT NULL,
                record_id INTEGER NOT NULL,
                sira_no INTEGER NOT NULL,
                ad_soyad TEXT NOT NULL DEFAULT '',
                tc_kimlik TEXT NOT NULL DEFAULT '',
                gorev_yeri TEXT NOT NULL DEFAULT '',
                unvan TEXT NOT NULL DEFAULT '',
                tarih TEXT NOT NULL DEFAULT '',
                yil INTEGER,
                sayi INTEGER,
                removed_at TEXT,
                removed_reason TEXT NOT NULL DEFAULT '',
                created_at TEXT NOT NULL,
                UNIQUE(approval_list_id, record_id)
            );

            CREATE INDEX IF NOT EXISTS idx_approval_list_items_list
                ON approval_list_items(approval_list_id);
            CREATE INDEX IF NOT EXISTS idx_approval_list_items_record
                ON approval_list_items(record_id);
            """
        )



def create_approval_list_group(
    connection: sqlite3.Connection,
    record_ids: Sequence[int],
    belge_turu: str,
    action_type: str = "MANUAL",
) -> Optional[int]:
    ids = list(dict.fromkeys(int(record_id) for record_id in record_ids))
    if not ids:
        return None
    placeholders = ",".join("?" for _ in ids)
    rows = connection.execute(
        f"""
        SELECT id, belge_turu, ad_soyad, tc_kimlik, gorev_yeri, unvan, tarih, yil, sayi
        FROM records
        WHERE id IN ({placeholders})
          AND status='OLUR_LISTESINDE'
          AND belge_turu=?
        ORDER BY yil, sayi, id
        """,
        [*ids, belge_turu],
    ).fetchall()
    if not rows:
        return None

    now = datetime.now().isoformat(timespec="seconds")
    cursor = connection.execute(
        "INSERT INTO approval_lists(belge_turu,created_at,created_by_action) VALUES(?,?,?)",
        (belge_turu, now, clean_text(action_type).upper() or "MANUAL"),
    )
    list_id = int(cursor.lastrowid)

    for sira_no, row in enumerate(rows, start=1):
        connection.execute(
            """
            INSERT INTO approval_list_items(
                approval_list_id,record_id,sira_no,ad_soyad,tc_kimlik,gorev_yeri,
                unvan,tarih,yil,sayi,created_at
            )
            VALUES(?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                list_id, int(row["id"]), sira_no, row["ad_soyad"], row["tc_kimlik"],
                row["gorev_yeri"], row["unvan"], row["tarih"] or "",
                row["yil"], row["sayi"], now,
            ),
        )
    return list_id


def mark_approval_item_removed(connection: sqlite3.Connection, record_id: int, reason: str) -> None:
    connection.execute(
        """
        UPDATE approval_list_items
        SET removed_at=COALESCE(removed_at, ?),
            removed_reason=CASE
                WHEN TRIM(COALESCE(removed_reason,''))='' THEN ?
                ELSE removed_reason
            END
        WHERE record_id=? AND removed_at IS NULL
        """,
        (datetime.now().isoformat(timespec="seconds"), clean_text(reason), int(record_id)),
    )


def list_approval_groups() -> List[Dict[str, Any]]:
    with get_connection() as connection:
        rows = connection.execute(
            """
            SELECT
                al.id,
                al.belge_turu,
                al.created_at,
                al.created_by_action,
                COUNT(ali.id) AS total_count,
                SUM(CASE WHEN ali.removed_at IS NULL THEN 1 ELSE 0 END) AS active_count,
                SUM(CASE WHEN ali.removed_at IS NOT NULL THEN 1 ELSE 0 END) AS removed_count,
                SUM(CASE WHEN ali.removed_at IS NULL AND r.status='TESLIM_EDILDI' THEN 1 ELSE 0 END) AS delivered_count,
                SUM(CASE WHEN ali.removed_at IS NULL AND r.status='OLUR_LISTESINDE' THEN 1 ELSE 0 END) AS pending_count,
                SUM(CASE WHEN ali.removed_at IS NULL AND r.status='IPTAL' THEN 1 ELSE 0 END) AS cancelled_count
            FROM approval_lists al
            LEFT JOIN approval_list_items ali ON ali.approval_list_id=al.id
            LEFT JOIN records r ON r.id=ali.record_id
            GROUP BY al.id
            ORDER BY al.id DESC
            """
        ).fetchall()
    return [dict(row) for row in rows]


def get_approval_group_items(list_id: int, include_removed: bool = True) -> List[Dict[str, Any]]:
    with get_connection() as connection:
        sql = """
            SELECT ali.*, r.status AS current_status, r.delivered_at, r.cancelled_at
            FROM approval_list_items ali
            LEFT JOIN records r ON r.id=ali.record_id
            WHERE ali.approval_list_id=?
        """
        params: List[Any] = [int(list_id)]
        if not include_removed:
            sql += " AND ali.removed_at IS NULL"
        sql += " ORDER BY ali.sira_no, ali.id"
        rows = connection.execute(sql, params).fetchall()
    return [dict(row) for row in rows]


def approval_group_status(group: Dict[str, Any]) -> Tuple[str, str]:
    active = int(group.get("active_count") or 0)
    delivered = int(group.get("delivered_count") or 0)
    pending = int(group.get("pending_count") or 0)
    cancelled = int(group.get("cancelled_count") or 0)
    removed = int(group.get("removed_count") or 0)

    if active == 0:
        label = "⚪ Aktif kayıt yok"
    elif delivered == active:
        label = f"✅ Tamamlandı — {delivered}/{active}"
    elif delivered > 0:
        label = f"🟡 Kısmen Tamamlandı — {delivered}/{active}"
    else:
        label = f"🔵 Hazırlandı — 0/{active}"

    warnings = []
    if pending:
        warnings.append(f"{pending} kayıt henüz İmzalandı ve Teslim Edildi değil")
    if cancelled:
        warnings.append(f"{cancelled} iptal edilmiş kayıt var")
    if removed:
        warnings.append(f"{removed} kayıt listeden çıkarılmış")
    return label, " • ".join(warnings)


def create_approval_group_excel(list_id: int) -> bytes:
    rows = get_approval_group_items(list_id, include_removed=False)
    if not rows:
        raise ValueError("Bu Olur listesinde indirilebilecek aktif kayıt bulunmuyor.")
    data = []
    for index, row in enumerate(rows, start=1):
        data.append({
            "Sıra No": index,
            "Ad Soyad": row.get("ad_soyad", ""),
            "T.C. Kimlik No": row.get("tc_kimlik", ""),
            "Kurumu/Görev Yeri": row.get("gorev_yeri", ""),
            "Ünvanı": row.get("unvan", ""),
        })
    output = io.BytesIO()
    with pd.ExcelWriter(output, engine="openpyxl") as writer:
        pd.DataFrame(data).to_excel(writer, index=False, sheet_name="Olur Listesi")
        ws = writer.book["Olur Listesi"]
        for col, width in {"A":10,"B":30,"C":20,"D":42,"E":30}.items():
            ws.column_dimensions[col].width = width
        ws.freeze_panes = "A2"
    output.seek(0)
    return output.getvalue()


def create_approval_group_pdf(list_id: int) -> bytes:
    rows = get_approval_group_items(list_id, include_removed=False)
    if not rows:
        raise ValueError("Bu Olur listesinde indirilebilecek aktif kayıt bulunmuyor.")

    page_size = landscape(A4)
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=page_size)
    width, height = page_size
    headers = ["Sıra No","Ad Soyad","T.C. Kimlik No","Kurumu/Görev Yeri","Ünvanı"]
    widths = [50,155,105,285,160]
    left = 28
    top = height - 48
    row_h = 28

    def draw_header(y):
        c.setFont(BOLD_FONT,11)
        c.drawCentredString(width/2,height-24,"BAŞARI BELGESİ OLUR LİSTESİ")
        x = left
        c.setFont(BOLD_FONT,7.3)
        for header, col_width in zip(headers,widths):
            c.rect(x,y-row_h,col_width,row_h)
            c.drawCentredString(x+col_width/2,y-18,header)
            x += col_width
        return y-row_h

    y = draw_header(top)
    c.setFont(MAIN_FONT,7.0)

    for index, row in enumerate(rows, start=1):
        if y-row_h < 35:
            c.showPage()
            y = draw_header(top)
            c.setFont(MAIN_FONT,7.0)
        values = [
            str(index),
            clean_text(row.get("ad_soyad","")),
            clean_text(row.get("tc_kimlik","")),
            clean_text(row.get("gorev_yeri","")),
            clean_text(row.get("unvan","")),
        ]
        x = left
        for value, col_width in zip(values,widths):
            c.rect(x,y-row_h,col_width,row_h)
            shown = value
            while shown and pdfmetrics.stringWidth(shown,MAIN_FONT,7.0) > col_width - 6:
                shown = shown[:-1]
            if shown != value and len(shown) > 1:
                shown = shown[:-1] + "…"
            c.drawCentredString(x+col_width/2,y-18,shown)
            x += col_width
        y -= row_h

    c.save()
    buffer.seek(0)
    return buffer.getvalue()


def get_home_dashboard_stats() -> Dict[str, int]:
    """Ana sayfa için salt-okunur özet sayıları döndürür."""
    current_year = date.today().year
    with get_connection() as connection:
        row = connection.execute(
            """
            SELECT
                COUNT(*) AS total_count,
                SUM(CASE WHEN status='TASLAK' THEN 1 ELSE 0 END) AS draft_count,
                SUM(CASE WHEN status='OLUR_LISTESINDE' THEN 1 ELSE 0 END) AS approval_count,
                SUM(CASE WHEN status='TESLIM_EDILDI' THEN 1 ELSE 0 END) AS delivered_count,
                SUM(CASE WHEN status='IPTAL' THEN 1 ELSE 0 END) AS cancelled_count,
                SUM(CASE WHEN belge_turu='BASARI' THEN 1 ELSE 0 END) AS success_count,
                SUM(CASE WHEN belge_turu='USTUN_BASARI' THEN 1 ELSE 0 END) AS superior_count,
                SUM(CASE WHEN CAST(substr(created_at,1,4) AS INTEGER)=? THEN 1 ELSE 0 END) AS created_this_year,
                SUM(CASE WHEN delivered_at IS NOT NULL
                          AND CAST(substr(delivered_at,1,4) AS INTEGER)=?
                         THEN 1 ELSE 0 END) AS delivered_this_year
            FROM records
            """,
            (current_year, current_year),
        ).fetchone()
    return {
        "total": int(row["total_count"] or 0),
        "draft": int(row["draft_count"] or 0),
        "approval": int(row["approval_count"] or 0),
        "delivered": int(row["delivered_count"] or 0),
        "cancelled": int(row["cancelled_count"] or 0),
        "success": int(row["success_count"] or 0),
        "superior": int(row["superior_count"] or 0),
        "created_this_year": int(row["created_this_year"] or 0),
        "delivered_this_year": int(row["delivered_this_year"] or 0),
        "year": current_year,
    }


def find_records_global(search_text: str, limit: int = 20) -> List[Dict[str, Any]]:
    query = clean_text(search_text)
    if not query:
        return []
    like = f"%{query}%"
    tc_query = clean_tc(query)
    with get_connection() as connection:
        rows = connection.execute(
            """
            SELECT *
            FROM records
            WHERE ad_soyad LIKE ?
               OR tc_kimlik LIKE ?
               OR unvan LIKE ?
               OR gorev_yeri LIKE ?
               OR (
                    yil IS NOT NULL AND sayi IS NOT NULL
                    AND (CAST(yil AS TEXT) || '/' || printf('%03d', sayi)) LIKE ?
               )
            ORDER BY datetime(created_at) DESC, id DESC
            LIMIT ?
            """,
            (like, f"%{tc_query or query}%", like, like, like, int(limit)),
        ).fetchall()
    return [row_to_record(row) for row in rows]


def row_to_record(row: sqlite3.Row) -> Dict[str, Any]:
    raw_number = row["sayi"]
    raw_year = row["yil"]
    return {
        "ID": row["id"],
        "BELGE_TURU": row["belge_turu"] if "belge_turu" in row.keys() else "BASARI",
        "TC_KIMLIK": row["tc_kimlik"],
        "AD_SOYAD": row["ad_soyad"],
        "UNVAN": row["unvan"],
        "GOREV_YERI": format_workplace_for_record(row["gorev_yeri"]),
        "TARIH": row["tarih"] or "",
        "YIL": raw_year,
        "SAYI": str(int(raw_number)).zfill(3) if raw_number is not None else "",
        "SAYI_INT": raw_number,
        "OLUR_YAZISI_TARIHI": row["olur_yazisi_tarihi"] if "olur_yazisi_tarihi" in row.keys() else "",
        "OLUR_YAZISI_SAYISI": row["olur_yazisi_sayisi"] if "olur_yazisi_sayisi" in row.keys() else "",
        "GEREKCE": row["gerekce"],
        "TALTIF_METNI": clean_text(row["taltif_metni"]) or DEFAULT_TALTIF_TEXT,
        "FOTO_PATH": row["foto_path"],
        "SIGNATURE_MODE": row["signature_mode"] if "signature_mode" in row.keys() else "WET",
        "SIGNER_NAME": row["signer_name"] if "signer_name" in row.keys() else "",
        "SIGNER_TITLE": row["signer_title"] if "signer_title" in row.keys() else "",
        "SIGNATURE_PATH": row["signature_path"] if "signature_path" in row.keys() else "",
        "CREATED_AT": row["created_at"],
        "UPDATED_AT": row["updated_at"],
        "STATUS": row["status"] if "status" in row.keys() else "TASLAK",
        "FINALIZED_AT": row["finalized_at"] if "finalized_at" in row.keys() else None,
        "DELIVERED_AT": row["delivered_at"] if "delivered_at" in row.keys() else None,
        "REOPENED_AT": row["reopened_at"] if "reopened_at" in row.keys() else None,
        "REOPEN_REASON": row["reopen_reason"] if "reopen_reason" in row.keys() else "",
        "CANCELLED_AT": row["cancelled_at"] if "cancelled_at" in row.keys() else None,
        "CANCEL_REASON": row["cancel_reason"] if "cancel_reason" in row.keys() else "",
        "RECORD_FINGERPRINT": row["record_fingerprint"] if "record_fingerprint" in row.keys() else "",
    }


def record_number_label(record: Dict[str, Any]) -> str:
    year = record.get("YIL")
    number = record.get("SAYI_INT")
    if year is None or number is None:
        return "Numara bekliyor"
    return f"{int(year)}/{int(number):03d}"


def recompute_counter(connection: sqlite3.Connection, belge_turu: str, year: Optional[int]) -> None:
    """Sayaç değerini halen kullanılan en yüksek numaraya indir/çıkar.

    İptal kayıtları tabloda kaldığı için numaraları korunur.
    Silinen veya numarası bırakılan son kayıt ise sayaç doğal olarak geri gelir.
    """
    if year is None:
        return
    belge_turu = clean_text(belge_turu).upper() or "BASARI"
    max_number = connection.execute(
        "SELECT COALESCE(MAX(sayi), 0) FROM records "
        "WHERE belge_turu = ? AND yil = ? AND sayi IS NOT NULL",
        (belge_turu, int(year)),
    ).fetchone()[0]
    connection.execute(
        "INSERT INTO counters(belge_turu, yil, last_number) VALUES (?, ?, ?) "
        "ON CONFLICT(belge_turu, yil) DO UPDATE SET last_number = excluded.last_number",
        (belge_turu, int(year), int(max_number or 0)),
    )


def add_audit(connection: sqlite3.Connection, action: str, record_id: Optional[int], details: str = "") -> None:
    connection.execute(
        "INSERT INTO audit_log(action, record_id, details, created_at) VALUES (?, ?, ?, ?)",
        (action, record_id, details, datetime.now().isoformat(timespec="seconds")),
    )


def list_records(search_text: str = "", year_filter: Optional[int] = None) -> List[Dict[str, Any]]:
    sql = "SELECT * FROM records WHERE 1=1"
    params: List[Any] = []

    if search_text.strip():
        query = f"%{search_text.strip()}%"
        sql += " AND (tc_kimlik LIKE ? OR ad_soyad LIKE ? OR unvan LIKE ? OR gorev_yeri LIKE ?)"
        params.extend([query, query, query, query])

    if year_filter is not None:
        # Kesinleşmiş / numaralı kayıt gerçek belge yılına göre;
        # numarasız Taslak ise sisteme eklendiği yıl (created_at) üzerinden süzülür.
        sql += (
            " AND COALESCE(yil, CAST(substr(created_at, 1, 4) AS INTEGER)) = ?"
        )
        params.append(int(year_filter))

    # Varsayılan liste: en son sisteme eklenen kayıt en üstte.
    sql += " ORDER BY datetime(created_at) DESC, id DESC"
    with get_connection() as connection:
        rows = connection.execute(sql, params).fetchall()
    return [row_to_record(row) for row in rows]


def get_record(record_id: int) -> Optional[Dict[str, Any]]:
    with get_connection() as connection:
        row = connection.execute("SELECT * FROM records WHERE id = ?", (record_id,)).fetchone()
    return row_to_record(row) if row else None


def existing_tc_count(tc_kimlik: str, exclude_id: Optional[int] = None) -> int:
    sql = "SELECT COUNT(*) FROM records WHERE tc_kimlik = ?"
    params: List[Any] = [tc_kimlik]
    if exclude_id is not None:
        sql += " AND id <> ?"
        params.append(exclude_id)
    with get_connection() as connection:
        return int(connection.execute(sql, params).fetchone()[0])


def existing_names_for_tc(tc_kimlik: str, exclude_id: Optional[int] = None) -> List[str]:
    """Aynı T.C. numarasıyla kayıtlı ad-soyadları döndürür."""
    sql = "SELECT DISTINCT ad_soyad FROM records WHERE tc_kimlik = ?"
    params: List[Any] = [tc_kimlik]
    if exclude_id is not None:
        sql += " AND id <> ?"
        params.append(exclude_id)
    with get_connection() as connection:
        rows = connection.execute(sql, params).fetchall()
    return [clean_text(row[0]) for row in rows if clean_text(row[0])]


def normalize_name_for_match(value: Any) -> str:
    """Ad-soyadı Türkçe büyük/küçük harf farklarından bağımsız karşılaştırır."""
    text = clean_text(value)
    text = text.translate(str.maketrans({"I": "ı", "İ": "i"})).lower()
    return re.sub(r"\s+", " ", text).strip()


def tc_name_conflict_message(tc_kimlik: str, ad_soyad: str, exclude_id: Optional[int] = None) -> Optional[str]:
    """T.C. mevcutsa ve farklı bir ad-soyadla eşleşiyorsa kullanıcı mesajı döndürür."""
    entered_key = normalize_name_for_match(ad_soyad)
    existing_names = existing_names_for_tc(tc_kimlik, exclude_id=exclude_id)
    for existing_name in existing_names:
        if normalize_name_for_match(existing_name) != entered_key:
            return (
                f'Bu T.C. kimlik numarası sistemde “{existing_name}” adına kayıtlıdır. '
                "Farklı bir kişi adına kullanılamaz."
            )
    return None


def number_exists(year: int, number: int, exclude_id: Optional[int] = None, belge_turu: str = "BASARI") -> bool:
    belge_turu = clean_text(belge_turu).upper() or "BASARI"
    sql = "SELECT 1 FROM records WHERE belge_turu = ? AND yil = ? AND sayi = ?"
    params: List[Any] = [belge_turu, year, number]
    if exclude_id is not None:
        sql += " AND id <> ?"; params.append(exclude_id)
    with get_connection() as connection:
        return connection.execute(sql, params).fetchone() is not None


def peek_next_number(year: int, belge_turu: str = "BASARI") -> int:
    belge_turu = clean_text(belge_turu).upper() or "BASARI"
    with get_connection() as connection:
        counter = connection.execute("SELECT last_number FROM counters WHERE belge_turu = ? AND yil = ?", (belge_turu, year)).fetchone()
        max_record = connection.execute("SELECT COALESCE(MAX(sayi), 0) FROM records WHERE belge_turu = ? AND yil = ?", (belge_turu, year)).fetchone()[0]
    return max(int(counter[0]) if counter else 0, int(max_record or 0)) + 1


def reserve_next_number(connection: sqlite3.Connection, year: int, belge_turu: str = "BASARI") -> int:
    belge_turu = clean_text(belge_turu).upper() or "BASARI"
    if not connection.in_transaction:
        connection.execute("BEGIN IMMEDIATE")
    counter_row = connection.execute("SELECT last_number FROM counters WHERE belge_turu = ? AND yil = ?", (belge_turu, year)).fetchone()
    max_record = connection.execute("SELECT COALESCE(MAX(sayi), 0) FROM records WHERE belge_turu = ? AND yil = ?", (belge_turu, year)).fetchone()[0]
    next_number = max(int(counter_row[0]) if counter_row else 0, int(max_record or 0)) + 1
    connection.execute("INSERT INTO counters(belge_turu, yil, last_number) VALUES (?, ?, ?) ON CONFLICT(belge_turu, yil) DO UPDATE SET last_number = excluded.last_number", (belge_turu, year, next_number))
    return next_number


def sync_counter(connection: sqlite3.Connection, year: int, number: int, belge_turu: str = "BASARI") -> None:
    belge_turu = clean_text(belge_turu).upper() or "BASARI"
    connection.execute("INSERT INTO counters(belge_turu, yil, last_number) VALUES (?, ?, ?) ON CONFLICT(belge_turu, yil) DO UPDATE SET last_number = MAX(last_number, excluded.last_number)", (belge_turu, year, number))



def document_type_label(value: Any) -> str:
    return "Üstün Başarı Belgesi" if clean_text(value).upper() == "USTUN_BASARI" else "Başarı Belgesi"


def document_type_short_label(value: Any) -> str:
    return "Üstün Başarı" if clean_text(value).upper() == "USTUN_BASARI" else "Başarı"


def document_type_marker(value: Any) -> str:
    return "🏆" if clean_text(value).upper() == "USTUN_BASARI" else "🔷"


def document_type_marker_label(value: Any) -> str:
    return f"{document_type_marker(value)} {document_type_short_label(value)}"


def document_type_sort_value(value: Any) -> int:
    return 1 if clean_text(value).upper() == "USTUN_BASARI" else 0


def document_type_badge_html(value: Any) -> str:
    normalized = clean_text(value).upper() or "BASARI"
