# Toplu İşlemler açılır listesinin BaseWeb portalı select'in dışında oluştuğu için
# yalnız Toplu İşlemler seçeneklerini içeren listbox'ı istemci tarafında genişlet.
components.html(
    """
    <script>
    (function installBulkMenuWidthFix() {
        const doc = window.parent.document;

        function fixListbox(listbox) {
            const txt = (listbox.innerText || listbox.textContent || '');
            if (!txt.includes('Toplu Olur Listesine Ekle') ||
                !txt.includes('Toplu İmzalandı ve Teslim Edildi')) return;

            listbox.style.setProperty('min-width', '390px', 'important');
            listbox.style.setProperty('width', '390px', 'important');
            listbox.style.setProperty('max-width', '390px', 'important');

            let node = listbox.parentElement;
            for (let i = 0; node && i < 4; i++, node = node.parentElement) {
                if (node.getAttribute && node.getAttribute('data-baseweb') === 'popover') {
                    node.style.setProperty('min-width', '390px', 'important');
                    node.style.setProperty('width', '390px', 'important');
                    node.style.setProperty('max-width', '390px', 'important');
                    break;
                }
            }

            listbox.querySelectorAll('li').forEach((li) => {
                li.style.setProperty('white-space', 'nowrap', 'important');
                li.style.setProperty('min-width', '380px', 'important');
                li.style.setProperty('width', '380px', 'important');
            });
        }

        function scan() {
            doc.querySelectorAll('[role="listbox"]').forEach(fixListbox);
        }

        scan();
        const observer = new MutationObserver(scan);
        observer.observe(doc.body, {childList: true, subtree: true});
    })();
    </script>
    """,
    height=0,
    width=0,
)

