# Arama alanları yazma/silme sırasında kısa bir beklemeden sonra otomatik uygulanır.
# Streamlit'in varsayılan Enter/odak kaybı davranışı korunurken kullanıcı ayrıca Enter'a basmaz.
components.html(
    """
    <script>
    (function installInstantSearch() {
        const doc = window.parent.document;
        const marker = 'data-mia-instant-search';

        function attach(input) {
            if (input.getAttribute(marker) === '1') return;
            const placeholder = input.getAttribute('placeholder') || '';
            if (!placeholder.includes('Ad, T.C., ünvan veya görev yeri')) return;
            input.setAttribute(marker, '1');
            let timer = null;
            input.addEventListener('input', function () {
                window.clearTimeout(timer);
                const current = input;
                timer = window.setTimeout(function () {
                    if (!doc.body.contains(current)) return;
                    current.dispatchEvent(new Event('change', { bubbles: true }));
                    current.blur();
                }, 350);
            });
        }

        function scan() {
            doc.querySelectorAll('input').forEach(attach);
        }

        scan();
        const observer = new MutationObserver(scan);
        observer.observe(doc.body, { childList: true, subtree: true });
    })();
    </script>
    """,
    height=0,
    width=0,
)


