            if result["already_finalized"]:
                details.append(f"{result['already_finalized']} kayıt zaten Olur Listesinde veya teslim edilmişti")
            if result["not_draft"]:
                details.append(f"{result['not_draft']} belge Taslak durumda değildi")
            if result["missing"]:
                details.append(f"{result['missing']} kayıt bulunamadı")
            if details:
                st.info("; ".join(details) + ".")
            if result.get("approval_list_ids"):
                if st.button(
                    "📋 Oluşan Olur Listesini Aç / İndir",
                    key="open_latest_approval_lists",
                    use_container_width=True,
                ):
                    st.session_state.active_page = "approval_records"
                    st.rerun()
            if result.get("photo_missing"):
                st.warning(f"{len(result['photo_missing'])} kayıt fotoğrafı olmadığı için Taslakta bırakıldı.")
                for message in result["photo_missing"]:
                    st.write(f"- {message}")
            if result["invalid"]:
                st.error(f"{len(result['invalid'])} belge eksik bilgi nedeniyle işlenemedi.")
                for message in result["invalid"]:
                    st.write(f"- {message}")
            if st.button("Sonuç Bildirimini Kapat", key="bulk_result_close"):
                st.session_state.bulk_finalize_result = None
                st.rerun()


