            if d2.button("Seçimi Temizle",key="del_clear",use_container_width=True):
                for x in eligible: st.session_state[f"del_{x['ID']}"]=False
                st.rerun()
            ids=[]; cols=st.columns(2)
            for i,x in enumerate(eligible):
                with cols[i%2]:
                    if st.checkbox(f"{record_number_label(x)} • {x['AD_SOYAD']} • {x['UNVAN']}",key=f"del_{x['ID']}"):
                        ids.append(x["ID"])
